import{_ as s,o as a,c as i,ah as t}from"./chunks/framework.Cx6lfSeA.js";const k=JSON.parse('{"title":"MCP Display Helpers","description":"display(), displayForm(), rendererHtml(), and registerViewerResource() — server-side helpers to return prefab UIs from MCP tools.","frontmatter":{"description":"display(), displayForm(), rendererHtml(), and registerViewerResource() — server-side helpers to return prefab UIs from MCP tools.","head":[["link",{"rel":"canonical","href":"https://max-health-inc.github.io/prefab/guide/mcp-display"}],["meta",{"property":"og:url","content":"https://max-health-inc.github.io/prefab/guide/mcp-display"}],["meta",{"property":"og:description","content":"display(), displayForm(), rendererHtml(), and registerViewerResource() — server-side helpers to return prefab UIs from MCP tools."}]]},"headers":[],"relativePath":"guide/mcp-display.md","filePath":"guide/mcp-display.md","lastUpdated":1784766201000}'),n={name:"guide/mcp-display.md"};function l(r,e,h,p,o,d){return a(),i("div",null,[...e[0]||(e[0]=[t(`<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /prefab/guide/mcp-display.md for this page in Markdown format</div><h1 id="mcp-display-helpers" tabindex="-1">MCP Display Helpers <a class="header-anchor" href="#mcp-display-helpers" aria-label="Permalink to &quot;MCP Display Helpers&quot;">​</a></h1><p>When an MCP tool runs, it hands back a result. The display helpers let that result be a living UI instead of a wall of text. You build a component tree on the server, hand it to a helper, and the helper packages it into the exact shape an MCP host expects to render.</p><h2 id="the-mental-model" tabindex="-1">The mental model <a class="header-anchor" href="#the-mental-model" aria-label="Permalink to &quot;The mental model&quot;">​</a></h2><p>Think of every tool handler as three small steps:</p><ol><li><strong>Build</strong> — compose your screen from prefab components (a <code>Column</code>, a table, a form, a chart).</li><li><strong>Wrap</strong> — pass that tree to a display helper. The helper serializes it to the <code>$prefab</code> wire format and folds it into an MCP tool-result envelope.</li><li><strong>Return</strong> — hand the envelope straight back from your handler. Any host that speaks prefab paints it.</li></ol><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { display, Column, H1, autoTable } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@maxhealth.tech/prefab&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> listPatients</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> patients</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">query</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;SELECT * FROM patients&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> display</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Column</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">H1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Patients&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">autoTable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(patients)]), { title: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Patients&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>You never touch the envelope by hand. The helper knows where the JSON goes, which fields the host reads, and how to keep older and newer hosts happy.</p><h2 id="full-display-vs-incremental-update" tabindex="-1">Full display vs. incremental update <a class="header-anchor" href="#full-display-vs-incremental-update" aria-label="Permalink to &quot;Full display vs. incremental update&quot;">​</a></h2><p>There are two ways to send something back, and picking the right one keeps your UIs snappy.</p><p>Reach for a <strong>full display</strong> when the screen changes shape — a new list, a detail page, a form, an error or success card. The host swaps in the whole tree and renders it fresh.</p><p>Reach for an <strong>incremental update</strong> when the screen is already on the user&#39;s screen and you only need to nudge some values inside it — a counter ticking up, a status flipping to &quot;done&quot;, a freshly fetched total. Instead of re-sending the entire view, you send just the changed state, and the renderer merges it into the live store without rebuilding anything.</p><p>That split is the whole game: send a full view when the layout changes, send a patch when only the data does.</p><h2 id="chaining-tools" tabindex="-1">Chaining tools <a class="header-anchor" href="#chaining-tools" aria-label="Permalink to &quot;Chaining tools&quot;">​</a></h2><p>Because each handler returns a self-contained UI, tools compose naturally. A list view can carry a button whose click calls a detail tool; the detail view can carry one that opens an edit form; submitting the form calls a save tool. Each step is just another handler returning its own <code>display(...)</code>, so rich, multi-screen flows fall out of simple pieces.</p><p>→ See the <a href="/prefab/reference/api/mcp/">MCP API reference</a> for the full API: every helper, its options, and the tool-result shape.</p>`,16)])])}const u=s(n,[["render",l]]);export{k as __pageData,u as default};
